-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(
    materialized='incremental',
    incremental_strategy=dpf_incremental_strategy({"bigquery": "merge", "duckdb": "delete+insert"}),
    unique_key=["order_id"]
) }}

with
checked_input as (
    select
        order_id,
        line_number,
        customer_business_key,
        product_code,
        line_order_date,
        line_quantity,
        line_revenue,
        line_list_value
    from {{ ref("ecommerce__order_summary__checked") }}
),
step_02_data_aggregation as (
    select
        order_id,
        cast((count(*)) as {{ dpf_type('int') }}) as order_line_count,
        cast((sum(line_quantity)) as {{ dpf_type('int') }}) as order_units,
        cast((sum(line_revenue)) as {{ dpf_decimal_type(12, 2) }}) as order_revenue,
        cast((min(line_order_date)) as {{ dpf_type('date') }}) as order_first_line_date
    from checked_input
    group by
        order_id
)

select
    order_id,
    order_line_count,
    order_units,
    order_revenue,
    order_first_line_date
from step_02_data_aggregation
